    const email = `${toBm.replace(/\D/g, '')}@bombeiros.mg.gov.br`;
    try {
      const success = await sendEmailViaGas(sheetUrl, email, subjectTitle, messageBody);
      if (success) {
        addNotification(`E-mail enviado para ${email}`, 'success');
