            <div className="mb-6 p-4 bg-slate-50 rounded-xl border border-slate-100 text-slate-600 text-sm max-h-[150px] overflow-y-auto">
              <p className="font-bold mb-2">Itens selecionados ({selectedReturnIds.length}):</p>
