import { useState, useEffect } from 'react';
import { useTheme } from '../hooks/useTheme';
import { BookOpen, ArrowRightCircle } from 'lucide-react';
import { cn } from '../lib/utils';
import Image from 'next/image';
import LoginButtons from './LoginButtons';

export default function App() {
  const { theme } = useTheme();
  const [showInstructions, setShowInstructions] = useState(false);
  const [sessionToken, setSessionToken] = useState<string | null>(null);

  useEffect(() => {
    const storedToken = localStorage.getItem('sessionToken');
    if (storedToken) {
      setSessionToken(storedToken);
    }
  }, []);

  const handleLogin = (token: string) => {
    localStorage.setItem('sessionToken', token);
    setSessionToken(token);
  };

  const handleLogout = () => {
    localStorage.removeItem('sessionToken');
    setSessionToken(null);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-100 dark:bg-gray-800">
      {sessionToken ? (
        <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-500">
          <div className={`p-10 text-center text-white bg-gradient-to-b ${theme.gradient}`}>
            <h1 className="text-2xl font-bold mb-2">Bem-vindo(a) de Volta!</h1>
            <p className="text-sm">Você está logado.</p>
          </div>
          <LoginButtons onLogout={handleLogout} />
        </div>
      ) : (
        <div className="w-full max-w-4xl relative">
          <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-500">
            <div className={`p-10 text-center text-white bg-gradient-to-b ${theme.gradient} flex justify-between items-center`}>
              <Image
                src="/logo.png"
                alt="Logo"
                width={80}
                height={80}
                className="rounded-full"
              />
              <button
                onClick={() => setShowInstructions(true)}
                className="text-slate-400 hover:text-white transition-colors flex items-center gap-2 group"
                title="Manual de Instruções"
              >
                <span className="text-[10px] uppercase font-bold tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">Instruções de Uso</span>
                <div className="p-2 bg-white/5 rounded-full border border-white/10 group-hover:border-white/30">
                  <BookOpen className="w-5 h-5" />
                </div>
              </button>
            </div>
            <p className="text-gray-500 text-sm mb-6">
              Por favor, insira o token de acesso.
            </p>
            <LoginButtons onLogin={handleLogin} />
          </div>
        </div>
      )}
    </div>
  );
}

```


