          <div className="flex items-center gap-3">
            <div className={`hidden md:flex items-center gap-2 px-3 py-1.5 bg-black/20 rounded-xl border border-white/10`}>
              <User className={`w-3.5 h-3.5 ${theme.textLight}`} />
